// Store reactivo con Observer (simplificado como Redux/Signal)
function crearStore(estadoInicial) {
  let estado = estadoInicial;
  const suscriptores = new Set();

  return {
    getEstado() {
      return estado;
    },
    setEstado(nuevoEstado) {
      estado = { ...estado, ...nuevoEstado };
      suscriptores.forEach(fn => fn(estado));
    },
    suscribir(fn) {
      suscriptores.add(fn);
      fn(estado); // Notifica inmediatamente con el estado actual
      return () => suscriptores.delete(fn); // cleanup
    },
  };
}

const store = crearStore({ usuario: null, carrito: [], cargando: false });

// 'Componente' que reacciona al estado:
const cancelar = store.suscribir(estado => {
  console.log('Render:', estado.cargando ? 'Cargando...' : `Usuario: ${estado.usuario}`);
});

store.setEstado({ cargando: true });
store.setEstado({ cargando: false, usuario: 'Ana' });

cancelar(); // Desuscribe
store.setEstado({ usuario: 'Bob' }); // No notifica al componente cancelado

// Event Bus con historial y wildcards simplificado
function crearEventBusAvanzado() {
  const suscriptores = new Map();
  const historial = [];

  function emitirACanal(canal, dato) {
    const cbs = suscriptores.get(canal) ?? [];
    cbs.forEach(cb => cb(dato, canal));
  }

  return {
    on(canal, cb) {
      if (!suscriptores.has(canal)) suscriptores.set(canal, []);
      suscriptores.get(canal).push(cb);
      return () => {
        suscriptores.set(canal, suscriptores.get(canal).filter(c => c !== cb));
      };
    },
    emit(canal, dato) {
      historial.push({ canal, dato, ts: Date.now() });
      emitirACanal(canal, dato);
    },
    getHistorial(canal) {
      return canal ? historial.filter(e => e.canal === canal) : [...historial];
    },
  };
}

const bus = crearEventBusAvanzado();
bus.on('pedido:creado', p => console.log('Nuevo pedido:', p.id));
bus.on('pedido:creado', p => console.log('Email enviado a:', p.email));

bus.emit('pedido:creado', { id: 1, email: 'ana@test.com' });
bus.emit('pedido:creado', { id: 2, email: 'bob@test.com' });

console.log('Historial:', bus.getHistorial('pedido:creado').length); // 2

